// For each BOOKED appointment, decide if today is the day to send a reminder
// (appointment is tomorrow) or a post-visit follow-up (appointment was yesterday).
// Runs daily, so each booking gets each message exactly once — no state needed.
const rows = $input.all().map(i => i.json);
const fmt = (d) => d.toISOString().slice(0, 10);
const today = new Date();
const tomorrow = fmt(new Date(today.getTime() + 86400000));
const yesterday = fmt(new Date(today.getTime() - 86400000));
const out = [];
for (const r of rows) {
  if (String(r.Booked).toLowerCase() !== 'true') continue;
  let dateStr = r.Date || '';
  if (!dateStr && r.When) { const m = String(r.When).match(/\d{4}-\d{2}-\d{2}/); if (m) dateStr = m[0]; }
  if (!dateStr) continue;
  const name = String(r.Name || 'there').split(' ')[0];
  const biz = r.Business || 'us';
  const when = r.When || dateStr;
  const phone = r.Phone || '';
  const email = r.Email || '';
  const review = r.ReviewLink || '';
  let type = null;
  if (dateStr === tomorrow) type = 'reminder';
  else if (dateStr === yesterday) type = 'followup';
  if (!type) continue;
  let sms, subject, body;
  if (type === 'reminder') {
    sms = `Hi ${name}, a reminder of your appointment with ${biz} ${when}. Reply R to reschedule or C to cancel — see you then!`;
    subject = `Reminder: your appointment with ${biz}`;
    body = `Hi ${name},\n\nJust a friendly reminder of your appointment with ${biz} ${when}.\n\nNeed to change it? Reply to this email or give us a call.\n\nSee you then!\n${biz}`;
  } else {
    sms = `Hi ${name}, thanks for coming in to ${biz}! We'd love a quick review${review ? ': ' + review : ''}. Hope to see you again soon.`;
    subject = `Thanks from ${biz}`;
    body = `Hi ${name},\n\nThanks for visiting ${biz} — we hope everything went well!\n\nIf you have a moment, a quick review really helps us${review ? ': ' + review : ''}.\n\nThanks again,\n${biz}`;
  }
  out.push({ json: { type, name, biz, phone, email, sms, subject, body, hasPhone: !!phone, hasEmail: !!email } });
}
return out;
